.ds-button{display: inline-flex;
  align-items: center;
  justify-content: center;
  gap: 9px;
  border: 1px solid transparent;
  border-radius: 30px;
  padding: 11px 22px;
  min-height: 44px;
  font-size: 11px;
  font-weight: 650;
  position: relative;
  transition:
    transform 0.25s,
    background 0.25s,
    box-shadow 0.25s,
    border-color 0.25s;
  white-space: nowrap;}
.ds-button:hover{transform: translateY(-3px);}
.ds-button-primary{color: #1c1034;
  background: linear-gradient(105deg, #dc8cf3, #b292ff 58%, #8b8cff);
  box-shadow:
    0 6px 22px #9663ed30,
    inset 0 1px #f7dfff5c;}
.ds-button-primary:hover{box-shadow:
    0 9px 29px #9862ed55,
    inset 0 1px #ffffff70;
  background: linear-gradient(105deg, #e6a6f7, #c1a7ff 58%, #a4a4ff);}.ds-button{font-family:'Manrope Variable',sans-serif;line-height:1.7;}.ds-button:focus-visible{outline:2px solid #d6b9ff;outline-offset:5px}@media(prefers-reduced-motion:reduce){.ds-button{transition:none}.ds-button:hover{transform:none}}

