  font-size: 11px;
  font-weight: 650;
  position: relative;
  transition:
    transform 0.25s,
    background 0.25s,
    box-shadow 0.25s,
    border-color 0.25s;
  white-space: nowrap;}
.ds-button:hover{transform: translateY(-3px);}
.ds-button-secondary{border-color: #8271ba80;
  color: #eee3ff;
  background: linear-gradient(110deg, #151c36bb, #0a1022cc);}
.ds-button-secondary:hover{border-color: #c19af2;
  background: #35235070;
  box-shadow: 0 7px 24px #7046b52b;}.ds-button{font-family:'Manrope Variable',sans-serif;line-height:1.7;}.ds-button:focus-visible{outline:2px solid #d6b9ff;outline-offset:5px}@media(prefers-reduced-motion:reduce){.ds-button{transition:none}.ds-button:hover{transform:none}}

.ds-field{margin-bottom: 19px;
  min-width: 0;}
.ds-field label{display: block;
  margin-bottom: 8px;
  font-size: 12px;
  color: #dfddf2;}
.ds-field input,
.ds-field textarea{width: 100%;
  min-width: 0;
  min-height: 44px;
  font-size: 12px;
  color: #f2ebff;
  border: 1px solid #8490c640;
  border-radius: 7px;
  background: #18203cc2;
  padding: 11px 13px;
  resize: vertical;
  transition:
    border-color 0.2s,
    background 0.2s;}
.ds-field input::placeholder,
.ds-field textarea::placeholder{color: #aaa9c3;}
.ds-field input:focus,
.ds-field textarea:focus{border-color: #ba91eb;
  background: #1c2341;}
.ds-field [aria-invalid="true"]{border-color: #f29bb8;}.ds-field{font-family:'Manrope Variable',sans-serif;line-height:1.7;}.ds-field input{font:inherit;font-size:12px}.ds-field input:focus-visible{outline:2px solid #d6b9ff;outline-offset:5px}

.ds-project-card{border: 1px solid #758fc432;
  border-radius: 14px;
  overflow: hidden;
  background: linear-gradient(145deg, #111c3380, #0b14266e);
  height: 100%;
  transition:
    border-color 0.3s,
    box-shadow 0.3s,
    transform 0.3s;}
.ds-project-card:hover{transform: translateY(-6px);
  border-color: #a67bdf8c;
  box-shadow: 0 17px 40px #07091d80;}
.ds-project-info{min-width: 0;
  padding: 20px 21px 19px;}
.ds-project-info h3{font-size: 19px;}
.ds-project-info > p{font-size: 12px;
  line-height: 1.9;
  margin-top: 14px;
  max-width: 58ch;}
.ds-tags{display: flex;
  flex-wrap: wrap;
  gap: 7px;
  margin-top: 13px;}
.ds-tags > span{display: inline-flex;
  align-items: center;
  gap: 5px;
  padding: 3px 7px;
  border-radius: 4px;
  background: #1a285165;
  color: #d0d4ed;
  font-size: 9px;
  line-height: 1.5;}.ds-project-card{font-family:'Manrope Variable',sans-serif;line-height:1.7;color:#f3f3ff}.ds-project-info h3{margin:0;font-weight:650;line-height:1.25;letter-spacing:-.02em}.ds-project-info p{color:var(--muted)}@media(prefers-reduced-motion:reduce){.ds-project-card{transition:none}.ds-project-card:hover{transform:none}}

.ds-filter{background: #10193177;
  color: #c6c8e0;
  border: 1px solid #7f89b33d;
  border-radius: 28px;
  min-height: 40px;
  padding: 8px 21px;
  font-size: 11px;
  transition:
    background 0.2s,
    border-color 0.2s,
    color 0.2s;}
.ds-filter:hover{border-color: #b68eed;
  color: #eddbff;}
.ds-filter.ds-active{background: linear-gradient(110deg, #da85f1, #a98cff);
  color: #21122f;
  font-weight: 750;
  border-color: transparent;
  box-shadow: 0 5px 17px #925ee92b;}.ds-filter{font-family:'Manrope Variable',sans-serif;line-height:1.7;}.ds-filter:focus-visible{outline:2px solid #d6b9ff;outline-offset:5px}

.ds-main-nav{display: flex;
  align-items: center;
  justify-content: center;
  gap: 27px;
  margin-inline: auto;}
.ds-main-nav a{position: relative;
  color: #c5c6d9;
  font-size: 12px;
  padding: 14px 0;
  transition: color 0.2s;}
.ds-main-nav a:hover,
.ds-main-nav a.ds-active{color: #dcb9ff;}
.ds-main-nav a.ds-active::after{content: "";
  position: absolute;
  width: 5px;
  height: 3px;
  background: #b687ff;
  border-radius: 4px;
  bottom: 5px;
  left: calc(50% - 2px);
  box-shadow: 0 2px 9px #986aff;}.ds-main-nav{font-family:'Manrope Variable',sans-serif;line-height:1.7;}.ds-main-nav a{text-decoration:none}.ds-main-nav a:focus-visible{outline:2px solid #d6b9ff;outline-offset:5px}

.ds-stat-card{text-align: center;
  padding: 23px 12px 20px;
  border: 1px solid #9181c34a;
  border-radius: 12px;
  background: linear-gradient(145deg, #1d21412b, #111a332e);
  box-shadow: inset 0 1px #c6b3ff09;
  position: relative;}
.ds-stat-card strong{display: block;
  font-size: 31px;
  line-height: 1.3;
  font-weight: 700;
  letter-spacing: -0.035em;
  font-variant-numeric: tabular-nums;}
.ds-stat-card > span{font-size: 11px;
  color: #bdc0da;
  display: block;
  margin-top: 8px;}.ds-stat-card{font-family:'Manrope Variable',sans-serif;line-height:1.7;color:#f3f3ff}

.ds-timeline-item{position: relative;
  padding: 0 0 43px 37px;
  margin-left: 16px;
  border-left: 1px solid #b385f2a6;}
.ds-timeline-node{position: absolute;
  top: -1px;
  left: -15px;
  width: 29px;
  height: 29px;
  border: 1px solid #d2a6ff;
  border-radius: 50%;
  background: radial-gradient(circle at 35% 30%, #d989fa, #8b4bdd 70%);
  color: #f3ddff;
  display: grid;
  place-items: center;
  box-shadow:
    0 4px 15px #9454df4d,
    inset 0 0 0 3px #43246a;}.ds-timeline-item{font-family:'Manrope Variable',sans-serif;line-height:1.7;color:#f3f3ff}
